};X < !정보--;
셋팅-- > function() {
    scwin.gEmpNo = js_emp_no; // 세션정보

    scwin.gExplDisclsAcptNo = $c.frame.path("../").txb_acpt_no.getValue();
    scwin.gExplDisclsOrdNo = $c.frame.path("../").scwin.gExplDisclsOrdNo;
    scwin.gIsurCd = $c.frame.path("../").txb_isur_cd.getValue();
    // alert("gIsurCd--> : " + gIsurCd);

    txb_com_abbrv.setValue($c.frame.path("../").txb_com_abbrv.getValue());
    txb_emp_nm.setValue(js_emp_nm);
    txb_re_acptno.setValue(scwin.gExplDisclsAcptNo);
};

/**
 * @method
 * @name insert
 * @description insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    const vAcptNo = txb_acptno.getValue();
    if (vAcptNo.length !== 14) {
        await $c.win.alert("공시를 선택하세요.");
        return;
    }
    if (txa_remk.getValue().length > 200) {
        await $c.win.alert("비고는  200자이하만 입력할 수 있습니다.");
        return false;
    }
    dts_explanation_new.insertRow();
    dts_explanation_new.setCellData(1, "REDISCLS_ACPT_NO", scwin.gExplDisclsAcptNo);
    dts_explanation_new.setCellData(1, "EXPLDISCLS_ACPT_NO", txb_acptno.getValue());
    dts_explanation_new.setCellData(1, "REG_ID", scwin.gEmpNo);
    dts_explanation_new.setCellData(1, "REMK", txa_remk.getValue());

    // alert("gExplDisclsAcptNo -->> : " +gExplDisclsAcptNo);
    // alert("getObjectValue(txb_acptno) -->> : " +getObjectValue(txb_acptno));

    const vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer === true) {
        trs_explanation_new.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_explanation_new",
            action : "/ExplanationDisclosure.do",
            ref : "dts_explanation_new",
            target : "trs_explanation_new=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name img_search_onclick
 * @description img_search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_search_onclick = async function() {
    const winTitle = txb_com_abbrv.getValue() + " / 공시 제출현황";
    // var url = "/dsclmgt/ULDSTF30224.gfm";
    // rame.CreateFrame("DSCLLIST"+gIsurCd, url , winTitle, 70, 10, 630, 330+30, "window" , 0, 0, true);
    const options = {
        id: "ULDSTF30224",
        title: winTitle,
        type: "browserPopup",
        width: "700px",
        height: "500px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/dsclmgt/ULDSTF30224.gfm", options);
};

/**
 * @method
 * @name trs_explanation_new_OnSuccess
 * @description explanation new On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_explanation_new_OnSuccess = async function() {
    await $c.win.alert("성공적으로 처리 되었습니다.");
    await $c.win.closePopup();
    // 부모창 reload 처리해야함
    $c.frame.path("../").fn_reload();
};

/**
 * @method
 * @name trs_explanation_new_OnFail
 * @description explanation new On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_explanation_new_OnFail = async function() {
    await $c.win.alert('trs_explanation_new.OnFail() :' + trs_explanation_new.ErrorMsg);
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    await scwin.insert();
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.resizeToWin();
    // hidden 추가 (ysh)
    txb_re_acptno.hide();
    txb_acptno.hide();
    fn_GetParentValue();

    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_explanation_new",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_explanation_new=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.stf.doLogSave('ULDSTF30223.xml', SCREN_PROCS_TP_CD_01);
};

